  "jungle.howTo.1": "Вы застряли в джунглях — выбирайте, как выживать",
  "jungle.howTo.2": "Каждый выбор по-разному влияет на вашу HP и счет",
  "jungle.howTo.3": "Если ваша HP достигнет 0, игра закончится",
  "jungle.howTo.4": "Выживите во всех 8 сценариях, чтобы победить!",
  "jungle.scene6": "Вы находите раненую птицу. Что вы сделаете?",
  "jungle.s6c1": "Осторожно перенесите — это может привести вас к тропе (+5 HP, +25 оч.)",
  "jungle.s6c2": "Оставьте — забота отнимет энергию (0 HP, +10 оч.)",
  "jungle.scene7": "Река преграждает путь. Вода выглядит быстрой.",
  "jungle.s7c1": "Соберите плот из поваленных бревен (−5 HP, +40 оч.)",
  "jungle.s7c2": "Идите вверх по течению, чтобы найти мелкий переход (+10 HP, +20 оч.)",
  "jungle.scene8": "Вы видите дым вдали.",
  "jungle.s8c1": "Идите на дым — возможно, это спасение! (+15 HP, +45 оч.)",
  "jungle.s8c2": "Избегайте — может быть лесной пожар (−5 HP, +15 оч.)",
  "jungle.scene9": "Наступает ночь. Вам нужно укрытие.",
  "jungle.s9c1": "Влезьте на высокое дерево, чтобы защититься от хищников (+10 HP, +30 оч.)",
  "jungle.s9c2": "Постройте наземное укрытие из веток (−5 HP, +35 оч.)",
  "jungle.scene10": "Вы находите фрукт, который не узнаете. Вы очень голодны.",
  "jungle.s10c1": "Съешьте — вы голодаете! (−20 HP, +30 оч.)",
  "jungle.s10c2": "Сначала проверьте маленький кусочек на коже (0 HP, +20 оч.)",
  "jungle.scene11": "На тропе свернулась большая змея.",
  "jungle.s11c1": "Медленно отойдите и найдите обход (+5 HP, +30 оч.)",
  "jungle.s11c2": "Попробуйте отпугнуть её (−25 HP, +40 оч.)",
  "jungle.scene12": "Вы слышите водопад — запасы воды критически низкие.",
  "jungle.s12c1": "Идите на звук, чтобы найти свежую воду (+20 HP, +35 оч.)",
  "jungle.s12c2": "Игнорируйте и продолжайте идти вперед (−15 HP, +20 оч.)",
  "jungle.scene13": "Быстро приближается гроза.",
  "jungle.s13c1": "Найдите возвышенность и укрытие (+10 HP, +25 оч.)",
  "jungle.s13c2": "Продолжайте движение, чтобы избежать этого (−10 HP, +30 оч.)",
  "jungle.scene14": "Вы находите пещеру. Становится темнее.",
  "jungle.s14c1": "Войдите в пещеру, чтобы укрыться (+15 HP, +30 оч.)",
  "jungle.s14c2": "Спите под деревом — возможно, в пещере кто-то есть (+5 HP, +20 оч.)",
  "jungle.scene15": "Вы вымотаны. Поляна впереди выглядит безопасной.",
  "jungle.s15c1": "Отдохните и восстановитесь (+20 HP, +20 оч.)",
  "jungle.s15c2": "Продолжайте — здесь отдых опасен (−5 HP, +30 оч.)",
  "jungle.scene16": "Вы находите старую карту, вырезанную на дереве.",
  "jungle.s16c1": "Следуйте направлению карты (+5 HP, +40 оч.)",
  "jungle.s16c2": "Игнорируйте — возможно, она устарела (0 HP, +10 оч.)",
  "jungle.scene17": "Дикие кабаны агрессивно пересекают ваш путь.",
  "jungle.s17c1": "Сразу заберитесь на ближайшее дерево (+5 HP, +30 оч.)",
  "jungle.s17c2": "Оставайтесь на месте и кричите (−20 HP, +35 оч.)",
  "jungle.scene18": "Вы находите заброшенный лагерь с припасами.",
  "jungle.s18c1": "Возьмите всё полезное (+20 HP, +50 оч.)",
  "jungle.s18c2": "Оставь — вдруг понадобится позже (0 HP, +10 очков)",
  "jungle.scene19": "Обезьяна украла твою сумку с едой!",
  "jungle.s19c1": "Беги за обезьяной (−10 HP, +40 очков)",
  "jungle.s19c2": "Отпусти — не стоит тратить силы (+0 HP, +15 очков)",
