  "briscola.howTo.3": "Выигрывай взятки, чтобы зарабатывать очки — Туз=11, 3=10, Король=4, Дама=3, Валет=2",
  "briscola.howTo.4": "Побеждает тот, у кого самый высокий счёт после того, как сыграны все карты",
  "card99.howTo.1": "Играй карты так, чтобы текущий итог оставался не выше 99",
  "card99.howTo.2": "Спецкарты: Король=0, Дама — держит, Валет=−10, Туз=1 или 11",
