  "dominoes.howTo.3": "Если сыграть нельзя — возьми из стопки",
  "dominoes.howTo.4": "Побеждает тот, кто первым опустошит руку (или наименьшее общее число очков на фишках)!",
  "farkle.howTo.1": "Брось 6 кубиков и отложи любые кубики, которые дают счёт",
